/**
 * dsh-web-file-preview — git diff 计算（宿主端，F2-B）。
 *
 * 对给定文件判断是否「在 git 仓库且与 HEAD 有变化」，并在有变化时返回其 diff：
 *  - not-git       → 文件不在任何 git 仓库内
 *  - outside-repo  → 文件解析后落在 git 仓库之外
 *  - no-changes    → 已跟踪但无未提交变更
 *  - untracked     → 存在新文件（未跟踪，无基线；hasDiff=true 但无 diff 文本）
 *  - error         → git 进程级故障（不可用/超时/输出超限），与「无变化」区分
 *  - 其余         → hasDiff=true + diff（`git diff HEAD -- <rel>` 统一 diff 文本）
 *
 * 说明（评审 C3/C4）：改用异步 execFile（promisify）——不阻塞服务事件循环
 * （原 spawnSync 在每个 diff 请求上同步跑 2~3 次 git，最大 3×8s，会卡死 SSE
 * 对话流）；显式 maxBuffer（spawnSync 默认 1MB 会让大 diff 静默判成 no-changes）。
 */

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { dirname, resolve, relative, isAbsolute } from "node:path";
import untildify from "untildify";

const execFileAsync = promisify(execFile);

/** diff 探测结果。 */
export interface GitDiffResult {
  hasDiff: boolean;
  untracked?: boolean;
  reason?: "not-git" | "outside-repo" | "no-changes" | "error";
  diff?: string;
  path?: string;
}

interface GitRun {
  ok: boolean;
  out: string;
  /** 进程级故障（git 缺失/超时/输出超限），区别于「命令正常退出且无输出」。 */
  failed: boolean;
}

/** git 输出上限（评审 C4：默认 1MB 会静默丢弃大 diff，显式放宽并标记失败）。 */
const MAX_GIT_OUTPUT_BYTES = 32 * 1024 * 1024;

/**
 * 执行 git 命令（异步、限时、限输出）。
 * @param args - git 参数。
 * @param timeoutMs - 超时毫秒。
 * @param opts - 选项：numericExitIsError=true 时，非零数字退出码（git 级错误，如 fatal 的
 *   128）判 failed。仅用于 status/diff 步骤——rev-parse 步骤不启用，因为「非 git 目录」
 *   同样以 128 退出，需要保留 not-git 语义（rev-parse 调用点用 top.ok/空输出来区分）。
 */
async function runGit(args: string[], timeoutMs = 8000, opts: { numericExitIsError?: boolean } = {}): Promise<GitRun> {
  try {
    const { stdout } = await execFileAsync("git", args, {
      encoding: "utf8",
      timeout: timeoutMs,
      maxBuffer: MAX_GIT_OUTPUT_BYTES,
    });
    return { ok: true, out: String(stdout ?? ""), failed: false };
  } catch (error) {
    // 超时 → error.killed；输出超限 → message 含 maxBuffer；命令缺失 → code ENOENT。
    // 推送前修复（P1）：git 正常路径以 0 退出；status/diff 步骤的非零数字退出码
    // （如 fatal 的 128）是 git 级错误，必须判 failed（此前漏判导致 git 报错被误当
    // 「无变化」）。rev-parse 步骤不启用此判定（非 git 目录同样 128，保留 not-git 语义）。
    const err = error as NodeJS.ErrnoException & { killed?: boolean };
    const failed =
      err.killed === true ||
      err.code === "ENOMEM" ||
      /maxBuffer/i.test(String(err.message)) ||
      err.code === "ETIMEDOUT" ||
      (opts.numericExitIsError === true && typeof err.code === "number");
    return { ok: false, out: "", failed };
  }
}

/**
 * 计算某文件相对其 git 仓库 HEAD 的 diff（若有）。
 * @param cwd - 会话 cwd（用于解析路径）。
 * @param path - 相对或绝对路径。
 * @returns diff 探测结果（async，不阻塞事件循环）。
 */
export async function computeGitDiff(cwd: string, path: string): Promise<GitDiffResult> {
  const resolved = resolve(cwd, untildify(path));
  const dir = dirname(resolved);

  const top = await runGit(["-C", dir, "rev-parse", "--show-toplevel"]);
  if (!top.ok || top.out.trim() === "") {
    return { hasDiff: false, reason: top.failed ? "error" : "not-git" };
  }
  const root = top.out.trim();
  const rel = relative(root, resolved);
  if (rel === "" || isAbsolute(rel) || rel.startsWith("..")) {
    return { hasDiff: false, reason: "outside-repo" };
  }

  const status = await runGit(["-C", root, "status", "--porcelain", "--", rel], 8000, { numericExitIsError: true });
  if (status.failed) {
    return { hasDiff: false, reason: "error" };
  }
  const lines = status.out.split("\n").map((s) => s.trim()).filter((s) => s !== "");
  if (lines.length === 0) {
    return { hasDiff: false, reason: "no-changes" };
  }
  const untracked = lines.some((l) => /^\?\?/.test(l));
  if (untracked) {
    return { hasDiff: true, untracked: true, path: rel };
  }

  // 评审（推送前修复 P0）：git diff 默认启用 textconv（第三方外部过滤器，由仓库内
  // .gitattributes + git config 配置），可让 git 以 dsh 进程身份执行任意命令。
  // `--no-ext-diff` 只关外部 diff 驱动、不关 textconv；故显式补 `--no-textconv` 封死
  // 该命令执行面（rev-parse/status 不触发 textconv，无需处理；filter 在 checkout 时触发、非本命令）。
  const diff = await runGit(["-C", root, "diff", "--no-ext-diff", "--no-textconv", "HEAD", "--", rel], 8000, { numericExitIsError: true });
  if (diff.failed) {
    return { hasDiff: false, reason: "error" };
  }
  if (!diff.ok || diff.out.trim() === "") {
    return { hasDiff: false, reason: "no-changes" };
  }
  return { hasDiff: true, diff: diff.out, path: rel };
}

packages/dsh-web-file-preview/src/mime.t.source:
/**
 * dsh-web-file-preview — 文件类型分组判定（纯函数，可单测）。
 *
 * 后缀→预览分组复用 `src/grouping.ts` 单一事实源（与浏览器端共用）；图片组
 * Content-Type 由成熟开源库 `mime` 提供（mime-db 全表，issue #12 / 决策 #47
 * approved：消除自写映射表的维护漂移；构建期由 esbuild 内联进产物，仍保持
 * 零运行时依赖）。
 *  - image        → 浏览器可解码的图片（直接 <img>）
 *  - renderedMd   → Markdown（marked 渲染，可切原始）
 *  - renderedCode → 代码类（highlight.js 高亮，可切原始）
 *  - text         → 其它纯文本（等宽 <pre>）
 *  - other        → 其余二进制，提示不可预览
 */

import mime from "mime";

import { groupOfPath } from "./grouping.ts";

/** 预览分组。 */
export type PreviewGroup = "image" | "text" | "renderedMd" | "renderedCode" | "other";

/** 判定结果。 */
export interface PreviewKind {
  group: PreviewGroup;
  ext: string;
  /** 实际 Content-Type（图片用精确映射；文本类一律 text/plain 供按文本读取）。 */
  contentType: string;
}

/**
 * 按文件路径（或其 basename）判定预览分组与 Content-Type。
 * @param path - 请求的文件路径（只看扩展名）。
 */
export function previewKindOf(path: string): PreviewKind {
  const { group, ext } = groupOfPath(path);
  if (group === "image") {
    // mime.getType 自带小写归一；未知后缀回退 octet-stream（与原自写表兜底一致）。
    // 注：ico 由自写表的 image/x-icon 变为 mime-db 标准值 image/vnd.microsoft.icon，
    // 浏览器 <img> 与 Content-Type 嗅探均兼容，无行为回归。
    return { group: "image", ext, contentType: mime.getType(ext) ?? "application/octet-stream" };
  }
  if (group === "md") {
    return { group: "renderedMd", ext, contentType: "text/markdown; charset=utf-8" };
  }
  if (group === "code") {
    return { group: "renderedCode", ext, contentType: "text/plain; charset=utf-8" };
  }
  if (group === "text") {
    return { group: "text", ext, contentType: "text/plain; charset=utf-8" };
  }
  return { group: "other", ext, contentType: "application/octet-stream" };
}

packages/dsh-web-file-preview/src/relpat.source:
/**
 * dsh-web-file-preview — Markdown 相对引用路径展开（纯函数，双端共用）。
 *
 * U8 v2：供客户端把 md 内的相对图片/链接展开为可预览的绝对路径。纯逻辑、
 * 无 DOM / node 特定 API（宿主 tsc 与浏览器 esbuild 均可打包），可用 smoke 直测。
 *
 * 语义（对齐评审 §5.5 U8 v2 + issue #45）：
 *  - 相对引用（裸名 / ./ / ../）→ 相对「被预览文件所在目录」解析；
 *  - 绝对路径 `/x`、协议相对 `//host`、http(s)/mailto/tel/data/file URI → 不展开（null，保留原链接）；
 *  - query / fragment 尾巴丢弃（服务端只按 path 定位）；
 *  - `%20` 等编码在 pathname 上解码一次（文件名含空格/中文可正常解析）。
 * issue #45 新增：`resolveAbsolutePath`（绝对路径 → 规范化路径，供可预览后缀的
 * 绝对路径重写为 Modal 内跳转）与 `splitReferenceFragment`（剥离并解码
 * #fragment，供带锚点的文件引用在 Modal 内定位小节）。
 */

/**
 * 把相对引用解析为绝对路径（POSIX 语义，基于 file: URL）。
 * @param baseFile - 被预览文件的完整路径（如 /home/u/work/src/a.md）。
 * @param reference - md 内的引用（相对路径 / 绝对路径 / URL）。
 * @returns 规范化绝对路径；不适用（协议相对/外域/绝对根/无法解析）→ null。
 */
export function resolveRelativePath(baseFile: string, reference: string): string | null {
  if (typeof reference !== "string" || reference === "") return null;
  // 已是服务端 API 前缀（幂等保护：二次渲染不再重写）。
  if (reference.startsWith("/api/")) return null;
  // 绝对路径（/x）与 web 根语义保留（v2 约定：不重写）。
  if (reference.startsWith("/")) return null;
  // 锚点/查询-only ≠ 文件引用。
  if (reference.startsWith("#")) return null;
  // 协议相对与外域一律保留；data:/blob/file 等非文件语义保留。
  if (/^(?:[a-zA-Z][a-zA-Z0-9+.-]*:|\/\/)/.test(reference)) return null;
  try {
    const url = new URL(reference, "file://" + baseFile.replace(/\\/g, "/"));
    // file: 之外的协议（理论上不会到这，稳妥起见）不展开。
    if (url.protocol !== "file:") return null;
    // //host 形态会被并入 host：外域引用不展开。
    if (url.host !== "") return null;
    const pathname = url.pathname; // 已做 . / .. 规范化；query/hash 不计入 pathname。
    return decodeSafePath(pathname);
  } catch {
    return null;
  }
}

/** 解码 URL pathname（%20 等）；非法编码序列原样保留。 */
function decodeSafePath(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

/**
 * 把绝对路径引用解析为规范化绝对路径（POSIX 语义，基于 file:///）。
 * issue #45：模型生成的 md 文档常用仓库绝对路径互引（AGENTS.md / 设计文档尤甚）；
 * 服务端 file 路由本就接受绝对 path 参数（不做 cwd 逃逸拦截，见 src/routes.ts
 * 文件头约定），客户端据此把可预览后缀的绝对路径重写为 Modal 内跳转。
 * @param reference - 以单个 / 开头的文件系统绝对路径引用（/api/ 幂等与协议相对
 *   由调用方 rewriteTarget 先行排除；`//host` 协议相对形态此处拒绝）。
 * @returns 规范化绝对路径（. / .. 归一、%20 等编码解码一次）；不适用 → null。
 */
export function resolveAbsolutePath(reference: string): string | null {
  if (typeof reference !== "string" || !reference.startsWith("/")) return null;
  if (reference.startsWith("//")) return null; // //host 协议相对 ≠ 文件系统绝对路径
  try {
    const url = new URL("file://" + reference.replace(/\\/g, "/"));
    if (url.protocol !== "file:" || url.host !== "") return null;
    const pathname = url.pathname; // . / .. 已规范化；query/hash 不计入 pathname。
    return decodeSafePath(pathname);
  } catch {
    return null;
  }
}

/** 引用拆分结果：去掉 #fragment 后的待解析引用 + 解码后的 fragment（无则 null）。 */
export interface SplitRef {
  ref: string;
  fragment: string | null;
}

/**
 * 从引用中剥离 #fragment（issue #45 附带瑕疵：./f.md#g 此前 fragment 被丢弃，
 * Modal 内打开后无法定位到对应小节）。
 * 只按第一个 "#" 分割（此前 KEEP_RE 已排除带 scheme 的 URL，无 "##" 歧义面）；
 * fragment 做一次 %XX 解码（非法编码原样保留），与 GFM 标题 slug（未编码
 * unicode 文本）可直接比对。空 fragment（a.md#）视为无锚点。
 */
export function splitReferenceFragment(reference: string): SplitRef {
  const s = typeof reference === "string" ? reference : "";
  const hash = s.indexOf("#");
  if (hash < 0) return { ref: s, fragment: null };
  let decoded = s.slice(hash + 1);
  try {
    decoded = decodeURIComponent(decoded);
  } catch { /* 非法编码原样保留 */ }
  return { ref: s.slice(0, hash), fragment: decoded === "" ? null : decoded };
}

